function Contador() {
  const [n, setN] = useState(0);
  const manejar = () => {
    setN(n + 5);
    setN((prev) => prev + 1);
  };
  return <button onClick={manejar}>{n}</button>;
}

function Saludo() {
  const [nombre, setNombre] = useState("Ana");
  const cambiar = () => {
    setNombre("Luis");
    console.log(nombre);
  };
  return <button onClick={cambiar}>{nombre}</button>;
}

function App() {
  const [cuenta, setCuenta] = useState(0);
  console.log("render", cuenta);
  useEffect(() => {
    setCuenta(1);
  }, []);
  return <p>{cuenta}</p>;
}

function Reloj() {
  const [seg, setSeg] = useState(0);
  useEffect(() => {
    const id = setInterval(() => {
      setSeg(seg + 1);
    }, 1000);
    return () => clearInterval(id);
  }, []);
  return <p>{seg}</p>;
}

function Perfil() {
  const [datos, setDatos] = useState(null);
  useEffect(() => {
    fetch("/api/perfil")
      .then((r) => r.json())
      .then((d) => setDatos(d));
  });
  return <p>{datos?.nombre}</p>;
}

function Panel() {
  const [a, setA] = useState(0);
  const [b, setB] = useState(0);
  console.log("render");
  const click = () => {
    setTimeout(() => {
      setA(1);
      setB(1);
    }, 0);
  };
  return <button onClick={click}>{a + b}</button>;
}

function Lista() {
  const [items, setItems] = useState(["Ana", "Luis"]);
  const agregar = () => setItems(["Zoe", ...items]);
  return (
    <>
      <button onClick={agregar}>Agregar</button>
      {items.map((nombre, i) => (
        <label key={i}>
          {nombre} <input />
        </label>
      ))}
    </>
  );
}

function Clics() {
  const clics = useRef(0);
  return (
    <button onClick={() => { clics.current++; }}>
      Clics: {clics.current}
    </button>
  );
}
